#!/usr/bin/env bash
# Local CI: the same checks .github/workflows/ci.yml runs, on your own machine.
# Generated by agent-ready. Keep the two in step: if a check matters enough to
# block a merge, it belongs in both. Nothing here calls a model API or spends money.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

step() { printf '\n==> %s\n' "$*"; }

# A separate venv on purpose: .venv is the one registered runs use
# (run_pipeline.sh), and installing the latest framework extras into it could
# shift the adapters under a pre-registered result.
VENV=.venv-ci
if [ ! -x "$VENV/bin/python" ]; then
  step "Create $VENV"; python3 -m venv "$VENV"
fi
step "Install (dev + all framework extras)"
"$VENV/bin/python" -m pip install --disable-pip-version-check -q -e ".[dev,all]"
step "Tests (offline, BENCH_MOCK=1)"; make test PYTHON="$VENV/bin/python"

echo
echo "Local CI passed."
